template <typename T>
T maximum(T a, T b) {
    return a > b ? a : b;
}

int main() {
    std::cout << maximum(3, 7) << " " << maximum(2.5, 1.5) << "\n";
    return 0;
}

#include <iostream>

template <typename T>
class Box {
public:
    explicit Box(T value) : value_(value) {}
    T get() const { return value_; }
private:
    T value_;
};

int main() {
    Box<int> a(4);
    Box<double> b(2.5);
    std::cout << a.get() << " " << b.get() << "\n";
    return 0;
}

#include <iostream>

template <typename A, typename B>
auto add(A a, B b) -> decltype(a + b) {
    return a + b;
}

